#!/usr/bin/env node
/**
 * E04-02 · BOOP taskboard panel in jsdom (client half).
 *
 * ⚠️ ALL DATA IN THIS FILE IS FIXTURE DATA — NOT LIVE HOST DATA.
 * The shapes are copied verbatim from the contract fixtures generated by the
 * Host half (e04-02-host, `src/host/tasks.ts`) and recorded in
 * `.work/contract-fixtures.json`; only titles/versions/group membership were
 * varied to cover the four display groups. Passing these tests does NOT prove
 * TB01/TB03/TB06/TB10, which need the real rc.2.1 host/browser run.
 *
 * Proves the client promises that must hold without a browser:
 *  - the four groups are rendered from the Host projection and finished cards
 *    keep the lifecycle/verification distinction (TB04: finished ≠ passed);
 *  - board and list views share ONE view model (never a second task state);
 *  - same-column reorder is local view state; the gated Host write command is
 *    attempted, its CAPABILITY_UNAVAILABLE refusal + audit sink is shown, and
 *    no success is fabricated (TB05/TB09);
 *  - keyboard/menu paths replace dragging and both views are keyboard-operable
 *    (TB08: arrows, Enter, Escape, complete-title toggle, collapse buttons);
 *  - empty / unreadable / error / partial-coverage / stale states are honest
 *    (FE-11; AT-19/FE-04: older request, projectionSeq and taskVersion never
 *    overwrite newer state);
 *  - no Markdown pipeline and no second React: task text is plain React text
 *    and the bundle keeps `require("react")` external (TB02/TB07);
 *  - the scoped sheet is BOOP-only, theme-aware, reduced-motion-aware, has no
 *    bare global rule and is removed on unmount (FE-09/FE-12).
 *
 * Run: node --test --test-force-exit tests/client/e04-02-taskboard.test.mjs
 */
import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { test, before, after } from 'node:test'
import React from 'react'
import { TaskboardPanel } from '../../lib/taskboard.test.bundle.cjs'

let dir
let window
let document
/** Imported AFTER the jsdom globals exist: react-dom decides its input-event
 * strategy at module load (`canUseDOM`); without this, jsdom text inputs take
 * React's legacy IE `propertychange` path and `onChange` never fires. */
let createRoot

before(async () => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'boop-e04-02-'))
  const { JSDOM } = await import('jsdom')
  const dom = new JSDOM('<!doctype html><html><body></body></html>', {
    pretendToBeVisual: true,
    url: 'http://localhost/',
  })
  window = dom.window
  document = dom.window.document
  globalThis.window = window
  globalThis.document = document
  ;({ createRoot } = await import('react-dom/client'))
})

after(() => {
  fs.rmSync(dir, { recursive: true, force: true })
})

const tick = (ms = 120) => new Promise((resolve) => setTimeout(resolve, ms))
/** React 18's concurrent root commits after a scheduler turn in jsdom; give it room. */
const settle = () => tick(160)

/** Poll until `condition` holds (or fail loudly): jsdom commit timing is not fixed. */
async function waitFor(condition, what = 'condition', timeout = 5000) {
  const start = Date.now()
  while (Date.now() - start < timeout) {
    if (condition()) return
    await tick(20)
  }
  throw new Error(`timed out waiting for ${what}`)
}

async function renderPanel(call, until) {
  const host = document.createElement('div')
  document.body.appendChild(host)
  const root = createRoot(host)
  root.render(React.createElement(TaskboardPanel, { call }))
  await waitFor(
    until ?? (() => host.querySelector('[data-boop-column], [data-boop-taskboard-alert], [data-boop-taskboard-empty]')),
    'the taskboard to settle',
  )
  await tick(40)
  return {
    host,
    root,
    text: () => host.textContent ?? '',
    html: () => host.innerHTML,
    cards: (group) =>
      [...host.querySelectorAll(`[data-boop-column][data-boop-group="${group}"] [data-boop-task-card]`)],
    card: (taskId) => host.querySelector(`[data-boop-task-card][data-task-id="${taskId}"]`),
    cleanup: () => {
      root.unmount()
      host.remove()
    },
  }
}

