function groupFacts(tasks) {
  const order = [
    ['todo', '待开始'],
    ['in_progress', '进行中'],
    ['needs_me', '待我处理'],
    ['finished', '已结束'],
  ]
  return order.map(([key, label], index) => ({
    key,
    label,
    order: index + 1,
    count: tasks.filter((task) => task.displayGroup === key).length,
  }))
}

