/* ── call doubles ─────────────────────────────────────────────────────── */

function makeCall(overrides = {}) {
  const calls = []
  const call = async (endpoint, args) => {
    calls.push({ endpoint, args })
    const handler = overrides[endpoint]
    if (typeof handler === 'function') return handler(args, calls)
    if (endpoint === 'boopTasks/capabilities') return { ok: true, value: CAPABILITIES }
    if (endpoint === 'boopTasks/list') return { ok: true, value: listFacts() }
    if (endpoint === 'boopTasks/detail') return { ok: true, value: DETAIL }
    if (endpoint === 'boopTasks/setPriority') return { ok: true, value: REFUSAL }
    return { ok: false, error: { message: `unexpected endpoint ${endpoint}` } }
  }
  return { call, calls }
}

function deferred() {
  let resolve
  let reject
  const promise = new Promise((res, rej) => {
    resolve = res
    reject = rej
  })
  return { promise, resolve, reject }
}

const click = (element) => {
  assert.ok(element, 'expected element to click')
  element.click()
}

function dispatchKey(element, key) {
  element.dispatchEvent(new window.KeyboardEvent('keydown', { key, bubbles: true, cancelable: true }))
}

/* ── 1. four-group projection ─────────────────────────────────────────── */

test('E04-02 renders the four Host-projected groups with honest counts and status lines', async () => {
  const { call } = makeCall()
  const view = await renderPanel(call)
  const root = view.host.querySelector('[data-boop-taskboard]')
  assert.ok(root, 'the taskboard mounts inside the panel')

  const columns = [...view.host.querySelectorAll('[data-boop-column]')]
  assert.deepEqual(
    columns.map((column) => column.getAttribute('data-boop-group')),
    ['todo', 'in_progress', 'needs_me', 'finished'],
    'frozen group order todo → in_progress → needs_me → finished',
  )
  assert.deepEqual(columns.map((column) => column.querySelector('[data-boop-column-header] span').textContent), [
    '待开始',
    '进行中',
    '待我处理',
    '已结束',
  ])
  assert.deepEqual(columns.map((column) => column.querySelectorAll('[data-boop-task-card]').length), [1, 2, 2, 2])

  assert.equal(view.card('b_fixture_1').querySelector('[data-boop-task-status]').textContent, '执行中')
  assert.equal(view.card('b_fixture_10').querySelector('[data-boop-task-status]').textContent, '等待你批准')
  assert.match(view.card('b_fixture_10').textContent, /待决原因：等待你批准/, 'the pending decision is shown on the card')

  assert.match(view.text(), /本地排序：可用/, 'local sorting is advertised as available')
  assert.match(view.text(), /canCommit=false/, 'the write gate is stated honestly')
  assert.match(view.text(), /blockedBy: G02, G05/)
  assert.match(view.text(), /未启用 Markdown/, 'plain-text rendering is stated')
  assert.match(view.text(), /验收与审批不可由此界面修改/)
  view.cleanup()
})

test('E04-02 finished is not success: completed/cancelled/failed/waived stay distinguishable (TB04)', async () => {
  const { call } = makeCall()
  const view = await renderPanel(call)
  const passed = view.card('b_fixture_6')
  const cancelled = view.card('b_fixture_7')
  const failed = view.card('b_fixture_8')

  assert.match(passed.textContent, /已结束（验收通过）/)
  assert.match(cancelled.textContent, /已结束（已取消）/)
  assert.doesNotMatch(cancelled.textContent, /验收通过/, 'a cancelled task never reads as accepted')
  assert.match(failed.textContent, /验收未通过/, 'failed verification is surfaced, not hidden')
  assert.doesNotMatch(failed.textContent, /已结束/, 'a failed verification is not finished')
  assert.equal(failed.querySelector('[data-boop-task-status]').getAttribute('data-tone'), 'bad')
  assert.equal(cancelled.querySelector('[data-boop-task-status]').getAttribute('data-tone'), 'muted')
  assert.equal(passed.querySelector('[data-boop-task-status]').getAttribute('data-tone'), 'ok')
  view.cleanup()
})

/* ── 2. list view shares the same view model ──────────────────────────── */

test('E04-02 the list view shares one projection and its rows are keyboard-operable', async () => {
  const { call, calls } = makeCall()
  const view = await renderPanel(call)
  click(view.host.querySelector('[data-boop-taskboard-action="view-list"]'))
  await settle()

  assert.equal(view.host.querySelector('[data-boop-taskboard-board]'), null, 'board is replaced, not duplicated')
  const list = view.host.querySelector('[data-boop-taskboard-list]')
  assert.ok(list)
  assert.equal(
    view.host.querySelectorAll('[data-boop-list-row]').length,
    5,
    '已结束 starts collapsed, so its two rows are not rendered yet',
  )
  assert.deepEqual(
    [...view.host.querySelectorAll('[data-boop-list-group-header]')].map((header) => header.textContent.replace(/\d+$/, '')),
    ['▾待开始', '▾进行中', '▾待我处理', '▸已结束'],
    '已结束 starts collapsed like the upstream list view; every header is a toggle button',
  )
  click(view.host.querySelectorAll('[data-boop-list-group-header]')[3])
  await settle()
  const rows = [...view.host.querySelectorAll('[data-boop-list-row]')]
  assert.equal(rows.length, TASKS.length, 'every projected task appears once in the list')
  const visibleRow = rows[0]
  dispatchKey(visibleRow, 'Enter')
  await settle()
  const detailCall = calls.find((entry) => entry.endpoint === 'boopTasks/detail')
  assert.ok(detailCall, 'Enter asks the Host for the exact task detail')
  assert.deepEqual(detailCall.args, { request: { taskId: visibleRow.getAttribute('data-task-id') } })

  const drawer = view.host.querySelector('[data-boop-taskboard-drawer]')
  assert.ok(drawer, 'the detail drawer opens')
  for (const label of ['目标与禁止项', '当前执行与验收', '需要你做什么', '相关 Session', '交付证据', '审批', '简化时间线']) {
    assert.match(drawer.textContent, new RegExp(label), `detail section ${label} is present`)
  }
  assert.match(drawer.textContent, /boop:\/\/session\/sess-board@4:12/, 'evidence shows the drill-down address')
  assert.match(drawer.textContent, /本次详情限制/, 'stated limitations are shown')

  dispatchKey(document, 'Escape')
  await settle()
  assert.equal(view.host.querySelector('[data-boop-taskboard-drawer]'), null, 'Escape closes the dialog')
  view.cleanup()
})

/* ── 3. same-column reorder + gated write refusal ─────────────────────── */

test('E04-02 same-column reorder is local view state and the Host refusal is shown verbatim (TB05)', async () => {
  const { call, calls } = makeCall()
  const view = await renderPanel(call)
  const inProgressOrder = () =>
    view.cards('in_progress').map((node) => node.getAttribute('data-task-id'))
  assert.deepEqual(inProgressOrder(), ['b_fixture_1', 'b_fixture_2'])

  click(view.card('b_fixture_1').querySelector('[data-boop-task-move="down"]'))
  await settle()

  assert.deepEqual(inProgressOrder(), ['b_fixture_2', 'b_fixture_1'], 'the local view order changed immediately')
  const writeCall = calls.find((entry) => entry.endpoint === 'boopTasks/setPriority')
  assert.ok(writeCall, 'the semantic write-back command is generated')
  assert.deepEqual(writeCall.args, {
    request: {
      taskId: 'b_fixture_1',
      expectedVersion: 2,
      priority: 'column-position:2',
      order: ['b_fixture_2', 'b_fixture_1'],
      position: 2,
      direction: 'down',
      requestId: writeCall.args.request.requestId,
    },
  }, 'the request is the semantic same-column move, not a task-state change')

  const write = view.card('b_fixture_1').querySelector('[data-boop-task-write]')
  assert.ok(write, 'the write-back status is rendered')
  assert.equal(write.getAttribute('data-state'), 'rejected', 'the server refusal is reported as rejected')
  assert.match(write.textContent, /CAPABILITY_UNAVAILABLE|没有写回优先级/)
  assert.match(write.textContent, /write-mode-disabled|写模式在 G02\/G05 通过前保持关闭/)
  assert.match(write.textContent, /审计：ledger，已记录/, 'the refusal audit row is visible')
  const reordered = view.card('b_fixture_1')
  assert.equal(reordered.getAttribute('data-boop-lifecycle'), 'active', 'lifecycle is unchanged by a local reorder')
  assert.equal(
    reordered.getAttribute('data-boop-verification'),
    'not_requested',
    'verification is unchanged by a local reorder',
  )
  assert.equal(reordered.getAttribute('data-boop-authorization'), 'running', 'authorization is unchanged too')
  assert.equal(reordered.querySelector('[data-state="confirmed"]'), null, 'no fake success')
  view.cleanup()
})

