/* ── 4. keyboard alternative to dragging ──────────────────────────────── */

test('E04-02 keyboard paths replace dragging: roving card focus, collapse, title toggle, session jump (TB08)', async () => {
  const opened = []
  const { call } = makeCall()
  const host = document.createElement('div')
  document.body.appendChild(host)
  const root = createRoot(host)
  root.render(React.createElement(TaskboardPanel, { call, onOpenSession: (sessionId) => opened.push(sessionId) }))
  await waitFor(() => host.querySelector('[data-boop-column]'), 'the taskboard to settle')
  const view = {
    host,
    card: (taskId) => host.querySelector(`[data-boop-task-card][data-task-id="${taskId}"]`),
    cleanup: () => {
      root.unmount()
      host.remove()
    },
  }

  const first = view.card('b_fixture_1')
  first.focus()
  dispatchKey(first, 'ArrowDown')
  assert.equal(document.activeElement, view.card('b_fixture_2'), 'ArrowDown moves focus to the next card in the column')
  dispatchKey(document.activeElement, 'ArrowUp')
  assert.equal(document.activeElement, view.card('b_fixture_1'), 'ArrowUp moves focus back')

  // Every card action is a real button with an accessible name.
  for (const taskId of ['b_fixture_1', 'b_fixture_9']) {
    const cardNode = view.card(taskId)
    for (const button of cardNode.querySelectorAll('button')) {
      assert.ok(
        (button.getAttribute('aria-label') ?? button.textContent ?? '').trim().length > 0,
        `${taskId} button is labelled for screen readers`,
      )
    }
  }
  // Column collapse is a keyboard button with aria-expanded.
  const header = host.querySelector('[data-boop-column][data-boop-group="finished"] [data-boop-column-header]')
  assert.equal(header.getAttribute('aria-expanded'), 'true')
  click(header)
  await settle()
  assert.equal(header.getAttribute('aria-expanded'), 'false')
  assert.equal(host.querySelector('[data-boop-column][data-boop-group="finished"] [data-boop-task-card]'), null)
  click(header)
  await settle()

  // Complete-title toggle: the full title is reachable without hovering.
  const titleToggle = view
    .card('b_fixture_1')
    .querySelectorAll('[data-boop-task-open]')[1]
  assert.equal(titleToggle.getAttribute('aria-expanded'), 'false')
  click(titleToggle)
  await settle()
  assert.equal(titleToggle.getAttribute('aria-expanded'), 'true')

  // Session navigation passes the exact stable id.
  click(view.card('b_fixture_1').querySelector('[data-boop-task-session="open"]'))
  assert.deepEqual(opened, ['sess-board'])
  view.cleanup()
})

/* ── 5. empty / unreadable / error / partial states (FE-11) ───────────── */

test('E04-02 unreadable is never rendered as empty; error and partial coverage are honest (FE-11)', async () => {
  // (a) Host says available:false — this is NOT "no tasks".
  const unavailable = makeCall({
    'boopTasks/list': () => ({
      ok: true,
      value: listFacts([], { available: false, reason: 'ledger-unavailable', tasks: [], groups: [], total: 0 }),
    }),
  })
  const unavailableView = await renderPanel(unavailable.call)
  assert.ok(unavailableView.host.querySelector('[data-boop-taskboard-alert]'))
  assert.match(unavailableView.text(), /任务投影不可用/)
  assert.match(unavailableView.text(), /ledger-unavailable/)
  assert.doesNotMatch(unavailableView.text(), /当前没有任务/, 'unavailable is not emptiness')
  unavailableView.cleanup()

  // (b) Transport failure — retry path, no fabricated empty state.
  const broken = makeCall({
    'boopTasks/list': () => ({ ok: false, error: { message: 'connection refused' } }),
  })
  const brokenView = await renderPanel(broken.call)
  assert.match(brokenView.text(), /connection refused/)
  assert.ok(
    [...brokenView.host.querySelectorAll('button')].some((button) => button.textContent === '重试'),
    'a failed read can be retried',
  )
  brokenView.cleanup()

  // (c) Readable and genuinely empty.
  const empty = makeCall({
    'boopTasks/list': () => ({ ok: true, value: listFacts([], { projectionSeq: 8 }) }),
  })
  const emptyView = await renderPanel(empty.call)
  assert.match(emptyView.text(), /当前没有任务（真实空状态/)
  emptyView.cleanup()

  // (d) Partial coverage: Host paged/truncated its projection.
  const partialTasks = TASKS.slice(0, 2)
  const partial = makeCall({
    'boopTasks/list': () => ({
      ok: true,
      value: listFacts(partialTasks, {
        total: 9,
        page: { limit: 2, offset: 0, returned: 2, total: 9, hasMore: true, defaultLimit: 50, maxLimit: 100 },
        scan: { cap: 500, fetched: 2, ledgerTotal: 2, truncated: false },
      }),
    }),
  })
  const partialView = await renderPanel(partial.call)
  const notice = partialView.host.querySelector('[data-boop-taskboard-partial]')
  assert.ok(notice, 'partial coverage is announced')
  assert.match(notice.textContent, /当前显示 2 \/ 宿主报告 9/)
  assert.match(notice.textContent, /未显示的部分不会被当作不存在/)
  partialView.cleanup()
})

/* ── 6. stale responses (AT-19 / FE-04) ───────────────────────────────── */

test('E04-02 an older list response never overwrites newer state (AT-19/FE-04)', async () => {
  const pending = []
  const { call } = makeCall({
    'boopTasks/list': () => {
      const request = deferred()
      pending.push(request)
      return request.promise
    },
  })
  const view = await renderPanel(call, () => pending.length >= 1) // request #1 stays pending
  assert.equal(pending.length, 1)

  // The refresh button is disabled while the first read is in flight, so the
  // second overlapping read comes from the documented reconnect path.
  window.dispatchEvent(new window.Event('online'))
  await waitFor(() => pending.length === 2, 'the second overlapping list request')
  assert.equal(pending.length, 2)

  // The NEW request answers first with the newer projection.
  pending[1].resolve({
    ok: true,
    value: listFacts([TASKS[0]], { projectionSeq: 12, tasks: [{ ...TASKS[0], title: '新状态标题', taskVersion: 9 }] }),
  })
  await settle()
  assert.match(view.text(), /新状态标题/)

  // The OLD request answers afterwards with an older projection: it must lose.
  pending[0].resolve({
    ok: true,
    value: listFacts([TASKS[0]], { projectionSeq: 11, tasks: [{ ...TASKS[0], title: '旧状态标题', taskVersion: 8 }] }),
  })
  await settle()
  assert.match(view.text(), /新状态标题/, 'the newer response stays on screen')
  assert.doesNotMatch(view.text(), /旧状态标题/, 'the older response is discarded')
  const stale = view.host.querySelector('[data-boop-taskboard-stale]')
  assert.ok(stale, 'the discarded response is announced instead of silently swallowed')
  assert.match(stale.textContent, /较旧|projectionSeq/)
  view.cleanup()
})

