/* ── 8. scoped styles + unmount cleanup (FE-09/FE-12) ─────────────────── */

test('E04-02 scoped styles are BOOP-only, theme/reduced-motion aware and removed on unmount (FE-09/FE-12)', async () => {
  for (const tag of document.head.querySelectorAll('style[data-plugin-css]')) tag.remove()
  const { call } = makeCall()
  const view = await renderPanel(call)
  const style = document.head.querySelector('style[data-plugin-css="boop/taskboard"]')
  assert.ok(style, 'the taskboard sheet is injected under a BOOP-owned data-plugin-css tag')
  const css = style.textContent
  assert.ok(css.includes('[data-boop-taskboard]'), 'every surface is rooted at the BOOP-owned attribute')
  assert.ok(css.includes('body[data-ds-dark-theme] [data-boop-taskboard]'), 'dark theme follows the APP signal')
  assert.ok(css.includes('@media (prefers-reduced-motion: reduce)'), 'reduced motion is honoured')
  assert.equal(/(^|\n)\s*(html|body)\s*\{/.test(css), false, 'no bare global element rule')
  assert.equal(css.includes('.dsw-'), false, 'no host class is restyled')
  assert.equal(css.includes('@import'), false, 'no remote/upstream stylesheet import')
  // Every rule selector (lines before `{`) must stay inside the BOOP scope.
  const selectors = [...css.matchAll(/(^|\n)([^@\n][^\n{]*)\{/g)].map((match) => match[2].trim()).filter(Boolean)
  for (const selector of selectors) {
    const parts = selector.split(',').map((part) => part.trim())
    for (const part of parts) {
      assert.ok(
        part.startsWith('[data-boop-taskboard')
          || part.startsWith('body[data-ds-dark-theme] [data-boop-taskboard'),
        `unscoped selector: ${part}`,
      )
    }
  }

  view.cleanup()
  await settle()
  assert.equal(
    document.head.querySelector('style[data-plugin-css="boop/taskboard"]'),
    null,
    'unmount removes the whole sheet (FE-12)',
  )
})

